def WriteClientActionRequests(self, requests, cursor=None):
    """Writes messages that should go to the client to the db."""
    if not requests:
      return

    if cursor is None:
      cursor = self._client_action_requests_table.GenerateCursor()

    for request in requests:
      self._client_action_requests_table.WriteClientActionRequest(
          cursor, request.client_id, request.request_id,
          request.action_id, request.request)

    self._client_action_requests_table.Flush()

